int hgic_fwctrl_do_cmd(struct hgic_fwctrl *ctrl, u8 ifidx, u32 cmd_id, u8 *in, u32 in_len, u8 *out, u32 out_size)
{
    int ret = -1;
    struct sk_buff *skb  = NULL;
    struct sk_buff *resp = NULL;
    struct hgic_cmd_response receipt;
    unsigned long flags;

    if ((!in && in_len) || (!out && out_size)) {
        hgic_attach_error(-EINVAL, HGIC_ATTACH_COMMAND);
        return -EINVAL;
    }
    if(in_len > 2000){
        hgic_err("data len is too long\r\n");
        hgic_attach_error(-EINVAL, HGIC_ATTACH_COMMAND);
        return -EINVAL;
    }

    spin_lock_irqsave(&ctrl->lock, flags);
    if (ctrl->attach_task != current || ctrl->attach_command ||
        cmd_id != HGIC_CMD_GET_FW_INFO || ifidx != HGIC_WDEV_ID_STA ||
        in_len || !out || out_size != 24 || hgic_attach_failed()) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        return hgic_attach_failed();
    }
    ctrl->attach_command = true;
    spin_unlock_irqrestore(&ctrl->lock, flags);

    skb = hgic_alloc_ctrl_skb(ctrl, in_len);
    if (skb) {
        spin_lock_irqsave(&ctrl->lock, flags);
        ctrl->attach_skb = skb;
        spin_unlock_irqrestore(&ctrl->lock, flags);
        if (in && in_len > 0) {
            memcpy(skb->data, in, in_len);
            skb->data[in_len] = 0;
        }

        resp = hgic_fwctrl_send_cmd(ctrl, ifidx, cmd_id, skb, &receipt);
        if (resp) {
            spin_lock_irqsave(&ctrl->lock, flags);
            if (hgic_attach_failed())
                ret = hgic_attach_failed();
            else if (ctrl->receipt_error)
                ret = ctrl->receipt_error;
            else
                ret = hgic_ctrl_reply_copy(resp->data, resp->len, receipt.type,
                                          receipt.ifidx, receipt.opcode, receipt.cookie,
                                          out, out_size);
            spin_unlock_irqrestore(&ctrl->lock, flags);
            dev_kfree_skb_any(resp);
        } else if (hgic_attach_failed()) {
            ret = hgic_attach_failed();
        } else if (READ_ONCE(ctrl->receipt_error)) {
            ret = READ_ONCE(ctrl->receipt_error);
        }
        if (ret < 0) {
            hgic_attach_error(ret, HGIC_ATTACH_COPY);
        }
    } else {
        ret = -ENOMEM;
        hgic_attach_error(ret, HGIC_ATTACH_COMMAND);
    }
    return ret;

/* Caller holds lock. Poison all station waiters, not a later response chosen by
 * cookie alone. Boot/maintenance ownership is NOT qualified by this A1 change.
 */
static void hgic_fwctrl_bad_receipt(struct hgic_fwctrl *ctrl)
{
    struct hgic_cmd_response *resp;

    WRITE_ONCE(ctrl->receipt_error, -EPROTO);
    WRITE_ONCE(ctrl->bus->rx_failed, 1);
    hgic_attach_error(-EPROTO, HGIC_ATTACH_RX);
    list_for_each_entry(resp, &ctrl->pd_list, list) {
        if ((resp->type == HGIC_HDR_TYPE_CMD || resp->type == HGIC_HDR_TYPE_CMD2) && !resp->done) {
            resp->done = true;
            complete(&resp->cmpl);
        }
    }
}

/* USB/core ingress uses the same locked A1 waiter/copy-admission latch. */
void hgic_fwctrl_rx_error(struct hgic_fwctrl *ctrl)
{
    unsigned long flags;

    spin_lock_irqsave(&ctrl->lock, flags);
    hgic_fwctrl_bad_receipt(ctrl);
    spin_unlock_irqrestore(&ctrl->lock, flags);
}

static int hgic_fwctrl_rx_response(struct hgic_fwctrl *ctrl, struct sk_buff *skb)
{
    int find = 0;
    unsigned long flags;
    struct hgic_cmd_response *resp = NULL;
    int status;
    u16 cookie;

    spin_lock_irqsave(&ctrl->lock, flags);
    if (!hgic_ctrl_frame_valid(skb->data, skb->len)) {
        hgic_fwctrl_bad_receipt(ctrl);
        goto unlock;
    }
    cookie = get_unaligned((const u16 *)(skb->data + 6));
    list_for_each_entry(resp, &ctrl->pd_list, list) {
        if (resp->cookie == cookie) {
            /* Duplicate/replayed completion can never replace the first skb. */
            if (resp->done)
                goto unlock;
            if (resp->type == HGIC_HDR_TYPE_CMD || resp->type == HGIC_HDR_TYPE_CMD2) {
                if (ctrl->receipt_error ||
                    hgic_ctrl_reply_status(skb->data, skb->len, resp->type,
                                           resp->ifidx, resp->opcode, resp->cookie,
                                           &status)) {
                    hgic_fwctrl_bad_receipt(ctrl);
                    goto unlock;
                }
                /* A valid associated signed failure is observed here, before
                 * publishing the response/waking its waiter. Preserve the
                 * first response and earlier error; do not call bad_receipt
                 * or copy negative-response payload. Lock order is the
                 * existing FWCTRL lock -> attach-receipt lock.
                 */
                if (status < 0)
                    hgic_attach_error(status, HGIC_ATTACH_COMMAND);
            }
            resp->skb = skb;
            resp->done = true;
            complete(&resp->cmpl);
            find = 1;
            break;
        }
    }
    if (!find)
        hgic_fwctrl_bad_receipt(ctrl); /* unknown/late association: no future TX */
unlock:
    spin_unlock_irqrestore(&ctrl->lock, flags);
    if (!find) {
        dev_kfree_skb_any(skb);
    }
    return 0;

struct sk_buff *hgic_fwctrl_send_data(struct hgic_fwctrl *ctrl, struct sk_buff *skb, struct hgic_cmd_response *resp, u32 timeout)
{
    unsigned long flags;
    struct hgic_ctrl_hdr *hdr;

    if (!skb || !resp || skb->len != sizeof(struct hgic_ctrl_hdr) ||
        resp->cookie > HGIC_TX_COOKIE_MASK) {
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        dev_kfree_skb_any(skb);
        return NULL;
    }
    hdr = (struct hgic_ctrl_hdr *)skb->data;
    resp->type = hdr->hdr.type;
    resp->ifidx = hdr->hdr.ifidx;
    resp->opcode = HDR_CMDID(hdr);
    /* Direct boot/OTA/BT/tool callers cannot borrow init's command permission. */

    init_completion(&resp->cmpl);
    spin_lock_irqsave(&ctrl->lock, flags);
    if (ctrl->receipt_error || hgic_attach_failed() || ctrl->attach_task != current ||
        ctrl->attach_skb != skb || ctrl->attach_queued || !ctrl->attach_command ||
        timeout != HGIC_CMD_TIMEOUT || resp->type != HGIC_HDR_TYPE_CMD ||
        resp->ifidx != HGIC_WDEV_ID_STA ||
        resp->opcode != HGIC_CMD_GET_FW_INFO - HGIC_CMD_START ||
        le16_to_cpu(hdr->hdr.magic) != HGIC_HDR_TX_MAGIC ||
        le16_to_cpu(hdr->hdr.length) != skb->len ||
        le16_to_cpu(hdr->hdr.cookie) != resp->cookie || !ctrl->schedule) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        dev_kfree_skb_any(skb);
        return NULL;
    }
    ctrl->attach_queued = true;
    list_add(&resp->list, &ctrl->pd_list);
    spin_unlock_irqrestore(&ctrl->lock, flags);

    if (ctrl->txq.qlen > 4) {
        kfree_skb(skb_dequeue(&ctrl->txq));
        //hgic_err("ctrl txq full, drop data (%d)\r\n", ctrl->txq.qlen);
    }

    skb_queue_tail(&ctrl->txq, skb);
    ctrl->schedule(ctrl);
    if (timeout) {
        if (!wait_for_completion_timeout(&resp->cmpl, msecs_to_jiffies(timeout))) {
            hgic_attach_error(-ETIMEDOUT, HGIC_ATTACH_COMMAND);
            /* P3 must cancel owned UNSENT work; P2 does not free an async skb
             * or attach this stack waiter to it as a cancellation shortcut.
             */
        }
    }
    spin_lock_irqsave(&ctrl->lock, flags);
    list_del(&resp->list);
    spin_unlock_irqrestore(&ctrl->lock, flags);
#ifdef __RTOS__
    deinit_completion(&resp->cmpl);
#endif
    return resp->skb;

void hgic_fwctrl_release(struct hgic_fwctrl *ctrl)
{
    cancel_work_sync(&ctrl->work);
    hgic_fwctrl_clear_pdlist(ctrl);
    hgic_clear_queue(&ctrl->txq);
    hgic_clear_queue(&ctrl->rxq);
#ifdef __RTOS__
    skb_queue_head_deinit(&ctrl->rxq);
    skb_queue_head_deinit(&ctrl->txq);
    spin_lock_deinit(&ctrl->lock);
#endif
    if (ctrl->wq) {
        flush_workqueue(ctrl->wq);
        destroy_workqueue(ctrl->wq);
    }

int hgic_fwctrl_attach_fwinfo(struct hgic_fwctrl *ctrl, struct hgic_fw_info *info)
{
    unsigned long flags;
    int error;
    spin_lock_irqsave(&ctrl->lock, flags);
    if (ctrl->attach_called || ctrl->attach_task || !ctrl->wq) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        hgic_attach_error(-EPERM, HGIC_ATTACH_COMMAND);
        return hgic_attach_failed();
    }
    error = hgic_attach_command_begin();
    if (error) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        return error;
    }
    ctrl->attach_called = true;
    ctrl->attach_task = current;
    spin_unlock_irqrestore(&ctrl->lock, flags);
    error = hgic_fwctrl_get_fwinfo(ctrl, HGIC_WDEV_ID_STA, info);
    spin_lock_irqsave(&ctrl->lock, flags);
    ctrl->attach_task = NULL;
    spin_unlock_irqrestore(&ctrl->lock, flags);
    if (error != 24)
        hgic_attach_error(error < 0 ? error : -EPROTO, HGIC_ATTACH_COPY);
    return error;
}

int hgic_fwctrl_attach_tx_admit(struct hgic_fwctrl *ctrl, struct sk_buff *skb)
{
    unsigned long flags;
    const struct hgic_ctrl_hdr *hdr;
    int error = 0;
    spin_lock_irqsave(&ctrl->lock, flags);
    /* Check local object identity before inspecting any purported wire header.
     * Consume this permission once. No async pointer to the stack waiter exists.
     */
    if (!skb || ctrl->attach_skb != skb || !ctrl->attach_queued ||
        ctrl->attach_tx_consumed || hgic_attach_failed() || ctrl->receipt_error ||
        skb_is_nonlinear(skb) || skb->len != sizeof(*hdr)) {
        error = -EPERM;
    } else {
        hdr = (const struct hgic_ctrl_hdr *)skb->data;
        if (hdr->hdr.type != HGIC_HDR_TYPE_CMD || hdr->hdr.ifidx != HGIC_WDEV_ID_STA ||
            le16_to_cpu(hdr->hdr.magic) != HGIC_HDR_TX_MAGIC ||
            le16_to_cpu(hdr->hdr.length) != skb->len ||
            HDR_CMDID(hdr) != HGIC_CMD_GET_FW_INFO - HGIC_CMD_START)
            error = -EPERM;
        else {
            ctrl->attach_tx_consumed = true;
            ctrl->attach_skb = NULL;
        }
    }
    spin_unlock_irqrestore(&ctrl->lock, flags);
    if (error)
        hgic_attach_error(error, HGIC_ATTACH_TX_ADMIT);
    return error;

//command response
struct hgic_cmd_response {
    struct list_head list;
    unsigned short cookie;
    unsigned short opcode;
    unsigned char type;
    unsigned char ifidx;
    bool done; /* first response wins, including a signed firmware error */
    struct completion cmpl;
    struct sk_buff   *skb;
};

struct hgic_fwctrl {
    struct device      *dev;
    u16                 cookie;
    int                 receipt_error; /* inhibits subsequent station admission */
    /* Local P2 ownership only. Never store the stack response in an skb/URB.
     * Queue/URB/request cancellation and submit serialization remain P3.
     */
    struct task_struct *attach_task;
    struct sk_buff *attach_skb; /* identity comparison only, not an extra ref */
    bool attach_called;
    bool attach_command;
    bool attach_queued;
    bool attach_tx_consumed;
    spinlock_t          lock;    /*ctrl packet pending lock*/
    struct list_head    pd_list; /*ctrl packet pending queue (for sync cmd)*/
    struct sk_buff_head rxq;   /*fw ctrl packet rx queue*/
    struct sk_buff_head txq;   /*fw ctrl packet tx queue*/
    struct work_struct  work;  /*fw ctrl rx packet process work*/
    struct workqueue_struct *wq;
    u8                  qc_mode;
    u8                  radio_onoff;
    struct hgic_fw_info *fwinfo;
    struct hgic_bus *bus;
    void (*schedule)(struct hgic_fwctrl *ctrl);
    void (*rx_event)(struct hgic_fwctrl *ctrl, struct sk_buff *skb);
};

struct hgic_usb_buf {
    struct list_head  list;
    struct hgic_usb  *usbdev;
    struct urb       *urb;
    void             *data;
    int               flag;
};

struct hgic_usb {
    struct usb_device *udev;
    uint   ep_in, ep_out;
    uint   ep_out_size, ep_in_size;
    uint   status;
    struct list_head  tx_freeq;
    struct list_head  rx_freeq;
    struct list_head  used;
    struct semaphore  tx_sema;
    spinlock_t qlock;
    struct hgic_bus bus;
};

static void hgic_usb_cancle(struct hgic_usb *usbdev)
{
    unsigned long flags;
    struct hgic_usb_buf *buf, *n;

    spin_lock_irqsave(&usbdev->qlock, flags);
    list_for_each_entry_safe(buf, n, &usbdev->used, list) {
        usb_unlink_urb(buf->urb);
    }
    spin_unlock_irqrestore(&usbdev->qlock, flags);
}

static void hgic_usb_quiesce(struct hgic_usb *usbdev)
{
    unsigned long flags;
    struct hgic_usb_buf *buf;

    /* Stop resubmission and synchronously drain callbacks OUTSIDE qlock:
     * usb_kill_urb may sleep and callbacks acquire this same spinlock.
     */
    usbdev->status |= HGIC_USB_STATUS_STOP;
    for (;;) {
        struct urb *urb;
        spin_lock_irqsave(&usbdev->qlock, flags);
        if (list_empty(&usbdev->used)) {
            spin_unlock_irqrestore(&usbdev->qlock, flags);
            break;
        }
        buf = list_first_entry(&usbdev->used, struct hgic_usb_buf, list);
        urb = usb_get_urb(buf->urb);
        spin_unlock_irqrestore(&usbdev->qlock, flags);
        usb_kill_urb(urb);
        usb_free_urb(urb);
    }
}
static void hgic_usb_free(struct hgic_usb *usbdev)
{
    unsigned long flags;
    struct hgic_usb_buf *buf, *n;

    hgic_usb_quiesce(usbdev);
    spin_lock_irqsave(&usbdev->qlock, flags);
    list_for_each_entry_safe(buf, n, &usbdev->tx_freeq, list) {
        list_del(&buf->list);
        usb_free_urb(buf->urb);
        if(buf->data){
            hgic_err("skb is not free??\r\n");
            kfree_skb(buf->data);
            buf->data = NULL;
        }
        kfree(buf);
    }
    list_for_each_entry_safe(buf, n, &usbdev->rx_freeq, list) {
        list_del(&buf->list);
        kfree(buf->data);
        usb_free_urb(buf->urb);
        kfree(buf);
    }
    WARN_ON(!list_empty(&usbdev->used));
    spin_unlock_irqrestore(&usbdev->qlock, flags);

static struct hgic_usb_buf *hgic_usb_deq(struct hgic_usb *usbdev, struct list_head *q)
{
    struct hgic_usb_buf *buf = NULL;
    unsigned long flags;

    spin_lock_irqsave(&usbdev->qlock, flags);
    if (!list_empty(q)) {
        buf = list_first_entry(q, struct hgic_usb_buf, list);
        buf->flag |= HGIC_USB_BUF_FLAG_USED;
        list_del(&buf->list);
        list_add_tail(&buf->list, &usbdev->used);
    }
    spin_unlock_irqrestore(&usbdev->qlock, flags);
    return buf;
}

static void hgic_usb_enq(struct hgic_usb_buf *buf, struct list_head *q)
{
    unsigned long flags;

    spin_lock_irqsave(&buf->usbdev->qlock, flags);
    buf->flag &= ~HGIC_USB_BUF_FLAG_USED;
    list_del(&buf->list);
    list_add_tail(&buf->list, q);
    spin_unlock_irqrestore(&buf->usbdev->qlock, flags);

static void hgic_usb_tx_complete(struct urb *urb)
{
    struct hgic_usb_buf *buf = (struct hgic_usb_buf *)urb->context;
    struct hgic_usb     *usbdev = buf->usbdev;

    if (urb->status)
        hgic_attach_error(urb->status, HGIC_ATTACH_TX_COMPLETE);
    usbdev->bus.tx_complete(usbdev->bus.bus_priv, (struct sk_buff *)buf->data, !urb->status);
    buf->data = NULL;
    hgic_usb_enq(buf, &usbdev->tx_freeq);
    up(&usbdev->tx_sema);
}

static int hgic_usb_tx_packet(void *bus, struct sk_buff *skb)
{
    int ret = 0;
    int len = ALIGN(skb->len, 4);
    struct hgic_usb_buf *buf    = NULL;
    struct hgic_usb     *usbdev = container_of(bus, struct hgic_usb, bus);
    struct hgic_hdr *hdr = (struct hgic_hdr *)skb->data;
    bool token = false;

    /* P2 actual transport boundary: only the one init-owned command may pass.
     * This is not P3's atomic error/deadline versus submission fence.
     */
    if (!usbdev->bus.attach_tx_admit || !usbdev->bus.bus_priv) {
        ret = -EPERM;
        goto __fail;
    }
    ret = usbdev->bus.attach_tx_admit(usbdev->bus.bus_priv, skb);
    if (ret)
        goto __fail;
    if (!usbdev->ep_out_size) {
        ret = -EPROTO;
        goto __fail;
    }

    if (skb_is_nonlinear(skb) && skb_linearize(skb)) {
        ret = -ENOMEM;
        goto __fail;
    }
    hdr = (struct hgic_hdr *)skb->data;

    /* Stock retail REA0x1b3c8 unconditionally appends four transport bytes
     * at the endpoint packet boundary, not just URB_ZERO_PACKET. Keep the
     * protocol hdr.length at its original value and zero only wire padding.
     */
    if (IS_ALIGNED(len, usbdev->ep_out_size))
        len += 4;

    /* Object admission above already requires exact CMD/FWINFO. Never permit
     * CMD2 TX, data, credit, BT, maintenance or even BOOT ENTER here.
     */
    if (skb->len != sizeof(struct hgic_ctrl_hdr) || hdr->type != HGIC_HDR_TYPE_CMD) {
        ret = -EPERM;
        goto __fail;
    }
    if (len > skb->len) {
        int padding = len - skb->len;
        if (skb_tailroom(skb) < padding &&
            pskb_expand_head(skb, 0, padding, GFP_ATOMIC)) {
            ret = -ENOMEM;
            goto __fail;
        }
        skb_put_zero(skb, padding);
    }


    if ((usbdev->status & (HGIC_USB_STATUS_STOP | HGIC_USB_STATUS_ERR)) ||
        hgic_attach_failed()) {
        ret = -EIO;
        goto __fail;
    }

    ret = down_timeout(&usbdev->tx_sema, 1000);
    if (ret) {
        goto __fail;
    }
    token = true;

    if ((usbdev->status & (HGIC_USB_STATUS_STOP | HGIC_USB_STATUS_ERR)) ||
        hgic_attach_failed()) {
        ret = -EIO;
        goto __fail;
    }

    buf = hgic_usb_deq(usbdev, &usbdev->tx_freeq);
    if (buf == NULL) {
        ret = -ENOMEM;
        goto __fail;
    }
    buf->data = skb;
    usb_fill_bulk_urb(buf->urb, usbdev->udev, usb_sndbulkpipe(usbdev->udev, usbdev->ep_out),
                      skb->data, len, hgic_usb_tx_complete, buf);
    buf->urb->transfer_flags |= URB_ZERO_PACKET;
    ret = usb_submit_urb(buf->urb, GFP_ATOMIC);
    if (ret) {
        hgic_attach_error(ret, HGIC_ATTACH_TX_SUBMIT);
        hgic_err("usb_submit_urb failed, ret:%d\n", ret);
        goto __fail;
    }

    return ret;

__fail:
    hgic_attach_error(ret, HGIC_ATTACH_TX_SUBMIT);
    if (buf) {
        buf->data = NULL;
        hgic_usb_enq(buf, &usbdev->tx_freeq);
    }
    if (token)
        up(&usbdev->tx_sema);
    usbdev->bus.tx_complete(usbdev->bus.bus_priv, skb, 0);
    return ret;

__failed:
    hgic_attach_error(ret, HGIC_ATTACH_PROBE);
    if (published)
        usb_set_intfdata(intf, NULL);
    hgic_usb_quiesce(usbdev);
    if (usbdev->bus.remove) {
        usbdev->bus.remove(usbdev->bus.bus_priv);
    }
    hgic_usb_free(usbdev);
    if (device_ref)
        usb_put_dev(udev);
    kfree(usbdev);
    return ret;
}

static void hgic_usb_disconnect(struct usb_interface *intf)
{
    struct hgic_usb *usbdev = usb_get_intfdata(intf);
    hgic_dbg("Enter\n");
    if (usbdev) {
        usbdev->status |= HGIC_USB_STATUS_STOP;
        up(&usbdev->tx_sema);
        /* TX callbacks still reference bus_priv. Drain them before the
         * mac80211 core tears that object down, not after free_hw().
         */
        hgic_usb_quiesce(usbdev);
        if (usbdev->bus.remove) {
            usbdev->bus.remove(usbdev->bus.bus_priv);
        }
        hgic_usb_free(usbdev);
        usb_put_dev(usbdev->udev);
        kfree(usbdev);
        usb_set_intfdata(intf, NULL);
    }

static DEFINE_SPINLOCK(attach_lock);
static struct hgic_attach_receipt attach_receipt;
static struct wiphy *attach_wiphy;
static bool notifier_registered;
static bool usb_registered;

/* Caller holds attach_lock. Failure is sticky even following init success.
 * A later error does not retract an earlier completed init/copy receipt.
 */
static void attach_error_locked(int error, unsigned int phase)
{
    if (!attach_receipt.first_error) {
        attach_receipt.first_error = error < 0 ? error : -EIO;
        attach_receipt.first_phase = phase;
    }
    if (attach_receipt.init_state == HGIC_ATTACH_NOT_STARTED ||
        attach_receipt.init_state == HGIC_ATTACH_RUNNING) {
        attach_receipt.init_state = HGIC_ATTACH_FAILED;
        attach_receipt.init_done = 1;
    }
}

void hgic_attach_error(int error, unsigned int phase)
{
    unsigned long flags;
    spin_lock_irqsave(&attach_lock, flags);
    attach_error_locked(error, phase);
    spin_unlock_irqrestore(&attach_lock, flags);
}

int hgic_attach_failed(void)
{
    unsigned long flags;
    int error;
    spin_lock_irqsave(&attach_lock, flags);
    error = attach_receipt.first_error;
    spin_unlock_irqrestore(&attach_lock, flags);
    return error;
}

void hgic_attach_snapshot(struct hgic_attach_receipt *out)
{
    unsigned long flags;
    spin_lock_irqsave(&attach_lock, flags);
    *out = attach_receipt;
    spin_unlock_irqrestore(&attach_lock, flags);
}

int hgic_attach_command_begin(void)
{
    unsigned long flags;
    int error = 0;
    spin_lock_irqsave(&attach_lock, flags);
    if (attach_receipt.first_error)
        error = attach_receipt.first_error;
    else if (attach_receipt.init_state != HGIC_ATTACH_RUNNING ||
             attach_receipt.fwinfo_commands)
        error = -EPERM;
    else
        attach_receipt.fwinfo_commands = 1;
    if (error)
        attach_error_locked(error, HGIC_ATTACH_COMMAND);
    spin_unlock_irqrestore(&attach_lock, flags);
    return error;

static void attach_tx_complete(void *priv, struct sk_buff *skb, int success)
{
    struct hgics_wdev *hg = priv;
    if (success) {
        hg->status.tx_ok++;
        /* Never clear BUS_ERROR or the first-error receipt on later success. */
    } else {
        hg->status.tx_fail++;
        set_bit(HGIC_BUS_FLAGS_ERROR, &hg->bus->flags);
        hgic_attach_error(-EIO, HGIC_ATTACH_TX_COMPLETE);
    }
    dev_kfree_skb_any(skb);
}

static int attach_tx_admit(void *priv, struct sk_buff *skb)
{
    struct hgics_wdev *hg = priv;
    if (test_bit(HGICS_STATE_REMOVE, &hg->state)) {
        hgic_attach_error(-ESHUTDOWN, HGIC_ATTACH_TX_ADMIT);
        return -ESHUTDOWN;
    }
    return hgic_fwctrl_attach_tx_admit(&hg->ctrl, skb);
}

static void attach_tx_work(struct work_struct *work)
{
    struct hgics_wdev *hg = container_of(work, struct hgics_wdev, tx_work);
    struct sk_buff *skb;
    /* One command only. No credit query, poll, sleep, retry or data loop. */
    skb = skb_dequeue(&hg->ctrl.txq);
    if (skb) {
        if (test_bit(HGICS_STATE_REMOVE, &hg->state) || hgic_attach_failed())
            dev_kfree_skb_any(skb);
        else
            hg->bus->tx_packet(hg->bus, skb);
    }
    if (!skb_queue_empty(&hg->ctrl.txq))
        hgic_attach_error(-EPERM, HGIC_ATTACH_TX_ADMIT);
}

static void attach_schedule(struct hgic_fwctrl *ctrl)
{
    struct hgics_wdev *hg = container_of(ctrl, struct hgics_wdev, ctrl);
    if (!hg->tx_wq || test_bit(HGICS_STATE_REMOVE, &hg->state) || hgic_attach_failed()) {
        hgic_attach_error(-ESHUTDOWN, HGIC_ATTACH_TX_ADMIT);
        return;
    }
    queue_work(hg->tx_wq, &hg->tx_work);
}

static void attach_delay_init(struct work_struct *work)
{
    struct hgics_wdev *hg = container_of(work, struct hgics_wdev, delay_init);
    unsigned long flags;
    int error;
    spin_lock_irqsave(&attach_lock, flags);
    if (attach_receipt.first_error || !attach_receipt.init_queued ||
        attach_receipt.init_state != HGIC_ATTACH_NOT_STARTED || attach_receipt.init_starts) {
        attach_error_locked(attach_receipt.first_error ? attach_receipt.first_error : -EALREADY,
                            HGIC_ATTACH_INIT);
        spin_unlock_irqrestore(&attach_lock, flags);
        return;
    }
    attach_receipt.init_state = HGIC_ATTACH_RUNNING;
    attach_receipt.init_starts = 1;
    spin_unlock_irqrestore(&attach_lock, flags);

    /* No download/RUN/boot query, soft-credit mode, MAC fallback or restart. */
    error = hgic_fwctrl_attach_fwinfo(&hg->ctrl, &hg->fwinfo);
    if (error != 24) {
        hgic_attach_error(error < 0 ? error : -EPROTO, HGIC_ATTACH_INIT);
        return;
    }
    if (hgic_attach_failed())
        return;
    hg->ctrl.fwinfo = &hg->fwinfo;
    error = attach_register_hw(hg);
    if (error) {
        hgic_attach_error(error, HGIC_ATTACH_HW_REGISTER);
        return; /* no failed-init automatic unregister/unload/retry */
    }
    /* Netdev registration/rollback/removal notifiers are RTNL serialized.
     * Reacquire it after register_hw so removal cannot pass its unlist stage
     * while the final publication still observes an older REGISTER snapshot.
     * No netdev pointer/reference or device action is needed here.
     */
    rtnl_lock();
    spin_lock_irqsave(&attach_lock, flags);
    attach_receipt.hw_registered = 1;
    if (!attach_receipt.first_error && attach_receipt.init_state == HGIC_ATTACH_RUNNING &&
        attach_receipt.proc_registered && attach_receipt.netdev_registered == 1 &&
        attach_receipt.netdev_present && !attach_receipt.netdev_removed &&
        !attach_receipt.netdev_teardown && !test_bit(HGICS_STATE_REMOVE, &hg->state) &&
        !attach_receipt.netdev_up_seen && !test_bit(HGICS_STATE_START, &hg->state) &&
        hg->radio_off) {
        attach_receipt.init_state = HGIC_ATTACH_SUCCEEDED;
        attach_receipt.init_done = 1;
    } else if (attach_receipt.netdev_teardown || test_bit(HGICS_STATE_REMOVE, &hg->state)) {
        attach_error_locked(-ECANCELED, HGIC_ATTACH_INIT);
    } else if (!attach_receipt.netdev_present || attach_receipt.netdev_removed) {
        /* Local missing-device condition, NOT the unavailable errno from a
         * later REGISTER notifier or automatic-interface creation failure.
         */
        attach_error_locked(-ENODEV, HGIC_ATTACH_NETDEV_LOST);
    } else {
        attach_error_locked(-EPROTO, HGIC_ATTACH_INIT);
    }
    spin_unlock_irqrestore(&attach_lock, flags);
    rtnl_unlock();

static void attach_core_remove(void *priv)
{
    struct hgics_wdev *hg = priv;
    unsigned int i;
    unsigned long flags;
    if (!hg)
        return;
    set_bit(HGICS_STATE_REMOVE, &hg->state);
    clear_bit(HGICS_STATE_START, &hg->state);
    spin_lock_irqsave(&attach_lock, flags);
    /* Identifies expected core-removal notifications only; not P4 retirement. */
    attach_receipt.netdev_teardown = 1;
    if (attach_receipt.init_state == HGIC_ATTACH_NOT_STARTED ||
        attach_receipt.init_state == HGIC_ATTACH_RUNNING)
        attach_error_locked(-ECANCELED, HGIC_ATTACH_INIT);
    spin_unlock_irqrestore(&attach_lock, flags);
    if (hg->primitives_ready) {
        cancel_work_sync(&hg->delay_init);
        cancel_work_sync(&hg->detect_work);
        cancel_work_sync(&hg->test_work);
        del_timer_sync(&hg->detect_tmr);
        del_timer_sync(&hg->beacon_timer);
        cancel_work_sync(&hg->tx_work);
    }
    if (hg->hw_registered)
        ieee80211_unregister_hw(hg->hw); /* DOWN: no successful start/interface */
    if (hg->ctrl_ready)
        hgic_fwctrl_release(&hg->ctrl);
    if (hg->tx_wq)
        destroy_workqueue(hg->tx_wq);
    if (hg->hw_initialized)
        hg->hghw->ops->free(hg);
    if (hg->primitives_ready) {
        for (i = 0; i < IEEE80211_NUM_ACS; i++)
            hgic_clear_queue(&hg->data_txq[i]);
        hgic_clear_queue(&hg->trans_q);
        hgic_clear_queue(&hg->ack_q);
        hgic_clear_queue(&hg->evt_list);
    }
    /* P2 guards initialization stages, NOT P4 submitter/URB/ref retirement. */
    WRITE_ONCE(attach_wiphy, NULL);
    ieee80211_free_hw(hg->hw);

struct hgics_wdev {
    u8 magic[4];
    void *dev;
    spinlock_t lock;
    u16 data_cookie;
    u16 rx_cookie;
    int id, dev_id;
    unsigned long state;
    struct hgic_fw_info fwinfo;
    struct ieee80211_hw *hw;
    struct hgic_bus *bus;
    struct mac_address macaddr[4];
    struct ieee80211_supported_band sbands[IEEE80211_NUM_BANDS];
    struct hgics_vif *ap;
    struct hgics_vif *sta;
    struct hgics_vif *p2p;
    struct timer_list detect_tmr;
    struct timer_list beacon_timer;
    unsigned long last_rx;
    char *conf_file;
    const struct hgics_hw *hghw;
    bool primitives_ready;
    bool ctrl_ready;
    bool hw_initialized;
    bool hw_registered;

    int      txq_size;
    struct sk_buff_head data_txq[IEEE80211_NUM_ACS];
    struct sk_buff_head trans_q;    /*transferring queue*/
    struct sk_buff_head ack_q;      /*waitting queue for ack*/
    struct work_struct tx_work;
    struct work_struct delay_init;
    struct work_struct  detect_work;
    struct workqueue_struct *tx_wq;

    u32 beacon_int;
    u64 full_beacon_int;
    int power_level;
    u32 fw_freq;

    struct hgics_config *conf;
#ifdef CONFIG_HGIC_AH
    struct hgics_11ah_wdev ahdev;
#endif
    struct hgic_fwctrl  ctrl;
    struct hgic_bootdl  bootdl;
    struct hgics_procfs proc;
    struct hgics_status status;
    struct hgic_ota     ota;

struct hgic_bus {
    int type;
    int dev_id;
    int drv_tx_headroom;
    void *bus_priv;
    unsigned long flags;
    int bootdl_pktlen;
    int bootdl_cksum;
    int blk_size;
    int (*probe)(void *dev, struct hgic_bus *bus);
    int (*tx_packet)(void *bus, struct sk_buff *skb);
    /* P2: consume permission for the sole init-owned skb, never a wire token. */
    int (*attach_tx_admit)(void *hg, struct sk_buff *skb);
    void (*tx_complete)(void *hg, struct sk_buff *skb, int success);
    int (*rx_packet)(void *hg, u8 *data, int len);
    /* Internal RX rejection only; no query/recovery or backing ownership change. */
    void (*rx_error)(void *hg);
    int rx_failed; /* sticky for this bus lifetime; checked before RX submission */
    int (*reinit)(void *bus);
    void (*probe_post)(void *priv);
    void (*remove)(void *priv);
    int (*suspend)(void *priv);
    int (*resume)(void *priv);
};

int usb_hcd_submit_urb (struct urb *urb, gfp_t mem_flags)
{
	int			status;
	struct usb_hcd		*hcd = bus_to_hcd(urb->dev->bus);

	/* increment urb's reference count as part of giving it to the HCD
	 * (which will control it).  HCD guarantees that it either returns
	 * an error or calls giveback(), but not both.
	 */
	usb_get_urb(urb);
	atomic_inc(&urb->use_count);
	atomic_inc(&urb->dev->urbnum);
	usbmon_urb_submit(&hcd->self, urb);

	/* NOTE requirements on root-hub callers (usbfs and the hub
	 * driver, for now):  URBs' urb->transfer_buffer must be
	 * valid and usb_buffer_{sync,unmap}() not be needed, since
	 * they could clobber root hub response data.  Also, control
	 * URBs must be submitted in process context with interrupts
	 * enabled.
	 */

	if (is_root_hub(urb->dev)) {
		status = rh_urb_enqueue(hcd, urb, mem_flags);
	} else {
		status = map_urb_for_dma(hcd, urb, mem_flags);
		if (likely(status == 0)) {
			status = hcd->driver->urb_enqueue(hcd, urb, mem_flags);
			if (unlikely(status))
				unmap_urb_for_dma(hcd, urb);
		}
	}

	if (unlikely(status)) {
		usbmon_urb_submit_error(&hcd->self, urb, status);
		urb->hcpriv = NULL;
		INIT_LIST_HEAD(&urb->urb_list);
		atomic_dec(&urb->use_count);
		/*
		 * Order the write of urb->use_count above before the read
		 * of urb->reject below.  Pairs with the memory barriers in
		 * usb_kill_urb() and usb_poison_urb().
		 */
		smp_mb__after_atomic();

		atomic_dec(&urb->dev->urbnum);
		if (atomic_read(&urb->reject))
			wake_up(&usb_kill_urb_queue);
		usb_put_urb(urb);
	}
	return status;

static void __usb_hcd_giveback_urb(struct urb *urb)
{
	struct usb_hcd *hcd = bus_to_hcd(urb->dev->bus);
	struct usb_anchor *anchor = urb->anchor;
	int status = urb->unlinked;

	urb->hcpriv = NULL;
	if (unlikely((urb->transfer_flags & URB_SHORT_NOT_OK) &&
	    urb->actual_length < urb->transfer_buffer_length &&
	    !status))
		status = -EREMOTEIO;

	unmap_urb_for_dma(hcd, urb);
	usbmon_urb_complete(&hcd->self, urb, status);
	usb_anchor_suspend_wakeups(anchor);
	usb_unanchor_urb(urb);
	if (likely(status == 0))
		usb_led_activity(USB_LED_EVENT_HOST);

	/* pass ownership to the completion handler */
	urb->status = status;
	/*
	 * This function can be called in task context inside another remote
	 * coverage collection section, but kcov doesn't support that kind of
	 * recursion yet. Only collect coverage in softirq context for now.
	 */
	kcov_remote_start_usb_softirq((u64)urb->dev->bus->busnum);
	urb->complete(urb);
	kcov_remote_stop_softirq();

	usb_anchor_resume_wakeups(anchor);
	atomic_dec(&urb->use_count);
	/*
	 * Order the write of urb->use_count above before the read
	 * of urb->reject below.  Pairs with the memory barriers in
	 * usb_kill_urb() and usb_poison_urb().
	 */
	smp_mb__after_atomic();
